package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"
	"time"

	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"
)

const hmacSecret = "k8s-internal-signing-key-2024"

type TenantContext struct {
	TenantID   string `json:"tenant_id"`
	UserID     string `json:"user_id"`
	Role       string `json:"role"`
	Timestamp  int64  `json:"timestamp"`
	Signature  string `json:"signature"`
}

type ProxyHandler struct {
	db     *mongo.Database
	client *mongo.Client
}

func computeSignature(tenantID, userID, role string, ts int64) string {
	mac := hmac.New(sha256.New, []byte(hmacSecret))
	payload := fmt.Sprintf("%s|%s|%s|%d", tenantID, userID, role, ts)
	mac.Write([]byte(payload))
	return hex.EncodeToString(mac.Sum(nil))
}

func (h *ProxyHandler) validateTenantContext(r *http.Request) (*TenantContext, error) {
	authHeader := r.Header.Get("X-Tenant-Context")
	if authHeader == "" {
		return nil, fmt.Errorf("missing tenant context")
	}

	var tc TenantContext
	if err := json.NewDecoder(strings.NewReader(authHeader)).Decode(&tc); err != nil {
		return nil, fmt.Errorf("invalid tenant context: %w", err)
	}

	if time.Now().Unix()-tc.Timestamp > 300 {
		return nil, fmt.Errorf("expired tenant context")
	}

	expected := computeSignature(tc.TenantID, tc.UserID, tc.Role, tc.Timestamp)
	if !hmac.Equal([]byte(expected), []byte(tc.Signature)) {
		return nil, fmt.Errorf("invalid signature")
	}

	return &tc, nil
}

func (h *ProxyHandler) buildTenantFilter(tc *TenantContext, userFilter map[string]interface{}) bson.M {
	baseFilter := bson.M{"tenant_id": tc.TenantID}

	if tc.Role == "admin" {
		for k, v := range userFilter {
			baseFilter[k] = v
		}
		return baseFilter
	}

	safeFilter := sanitizeFilter(userFilter)
	for k, v := range safeFilter {
		baseFilter[k] = v
	}
	baseFilter["owner_id"] = tc.UserID
	return baseFilter
}

func sanitizeFilter(input map[string]interface{}) map[string]interface{} {
	result := make(map[string]interface{})
	for k, v := range input {
		if strings.HasPrefix(k, "$") {
			continue
		}
		switch val := v.(type) {
		case map[string]interface{}:
			result[k] = sanitizeNestedOperators(val)
		case string:
			result[k] = val
		case float64:
			result[k] = val
		case bool:
			result[k] = val
		}
	}
	return result
}

func sanitizeNestedOperators(input map[string]interface{}) interface{} {
	result := make(map[string]interface{})
	allowedOps := map[string]bool{"$eq": true, "$gt": true, "$lt": true, "$gte": true, "$lte": true, "$in": true}
	for k, v := range input {
		if strings.HasPrefix(k, "$") && !allowedOps[k] {
			continue
		}
		result[k] = v
	}
	return result
}

func (h *ProxyHandler) queryDocuments(w http.ResponseWriter, r *http.Request) {
	tc, err := h.validateTenantContext(r)
	if err != nil {
		http.Error(w, err.Error(), http.StatusUnauthorized)
		return
	}

	collection := r.URL.Query().Get("collection")
	if collection == "" || strings.ContainsAny(collection, ".$") {
		http.Error(w, "invalid collection", http.StatusBadRequest)
		return
	}

	var userFilter map[string]interface{}
	if err := json.NewDecoder(r.Body).Decode(&userFilter); err != nil {
		http.Error(w, "invalid filter body", http.StatusBadRequest)
		return
	}

	filter := h.buildTenantFilter(tc, userFilter)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cursor, err := h.db.Collection(collection).Find(ctx, filter)
	if err != nil {
		http.Error(w, "query failed", http.StatusInternalServerError)
		return
	}
	defer cursor.Close(ctx)

	var results []bson.M
	if err := cursor.All(ctx, &results); err != nil {
		http.Error(w, "decode failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func main() {
	ctx := context.Background()
	client, err := mongo.Connect(ctx, options.Client().ApplyURI("mongodb://localhost:27017"))
	if err != nil {
		log.Fatal(err)
	}

	handler := &ProxyHandler{
		db:     client.Database("multitenant_app"),
		client: client,
	}

	http.HandleFunc("/api/query", handler.queryDocuments)
	log.Println("Proxy listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
